  T('C11 Scrap all scraps exactly what Sell all would sell (kept fish stay), C14 cooler sort orders and keeps the real index on every row',()=>{ const e=[]; const sp=SP.filter(s=>s.r===0&&!s.meme).slice(0,3), lg=SP.find(s=>s.r===4); S.settings.sellR='all'; S.settings.sellP=0; S.cooler=[...sp.map((s,j)=>({id:s.id,kg:s.min,value:10+j,sh:0})),{id:lg.id,kg:lg.min,value:999,sh:0}]; const keep=S.cooler.filter(sellKeep).length; act('scrapall',{}); if(S.cooler.length!==keep) e.push('left '+S.cooler.length+', want '+keep); if(S.cooler.some(f=>!sellKeep(f))) e.push('a matching fish survived'); S.cooler=sp.map((s,j)=>({id:s.id,kg:s.min,value:10+j*100,sh:0})); for(const k of ['recent','old','value','aq','species']){ coolSort=k; const L=coolOrder(); if(L.length!==3||new Set(L.map(x=>x.i)).size!==3||L.some(x=>S.cooler[x.i]!==x.f)) e.push(k+': rows lost their index'); } coolSort='value'; const v=coolOrder().map(x=>salePrice(x.f)); if(v[0]<v[1]||v[1]<v[2]) e.push('value not high to low'); coolSort='recent'; if(coolOrder()[0].i!==2) e.push('newest not first'); coolSort='recent'; return e.length?{ok:false,detail:e.join('; ')}:{ok:true,detail:'scrap all + 5 sorts'}; });
