    const a=mk({hairStyle:'curly',hat:'none'}), b=mk({hairStyle:'coils',hat:'none'}); if(diff(a,b,0,ch)) e.push('coils differs from curly'); if(typeof drawCurly3!=='function'||CURLY_LOBES.length!==15) e.push('hand-drawn curly missing'); if(typeof hairTexture!=='function') e.push('no strand texture');
